function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function slug(value) {
  return String(value || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/-{2,}/g, '-');
}
const body = $json.body || $json;
const avatar = slug(body.avatar);
if (!avatar) {
  return [{ json: { query: "SELECT false AS ok, 'avatar is required' AS error, '[]'::jsonb AS references;" } }];
}
const query = `
SELECT
  true AS ok,
  COALESCE(jsonb_agg(jsonb_build_object(
    'assetId', asset_id,
    'avatar', avatar,
    'scene', scene,
    'classification', COALESCE(metadata->>'referenceClassification', 'supporting-reference'),
    'status', status,
    'isCanonical', COALESCE(is_canonical, false),
    'bucket', bucket,
    'objectPath', object_path,
    'url', '/minio/' || bucket || '/' || object_path,
    'reviewNotes', review_notes,
    'createdAt', created_at
  ) ORDER BY created_at DESC NULLS LAST), '[]'::jsonb) AS references,
  jsonb_build_object(
    'identityCanonCount', COUNT(*) FILTER (WHERE metadata->>'referenceClassification' = 'identity-canon'),
    'sceneCanonCount', COUNT(*) FILTER (WHERE metadata->>'referenceClassification' = 'scene-canon'),
    'candidateCount', COUNT(*) FILTER (WHERE metadata->>'referenceClassification' IN ('identity-candidate', 'scene-candidate')),
    'rejectedCount', COUNT(*) FILTER (WHERE metadata->>'referenceClassification' = 'rejected-reference')
  ) AS summary
FROM canonical_asset_registry
WHERE avatar = ${sql(avatar)}
  AND metadata->>'referenceIntake' = 'characters-console';
`;
return [{ json: { query } }];

const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') return [{ json: { ok: false, message: row.error || 'References could not load.' } }];
const references = typeof row.references === 'string' ? JSON.parse(row.references) : row.references;
const summary = typeof row.summary === 'string' ? JSON.parse(row.summary) : row.summary;
return [{ json: { ok: true, references: references || [], summary: summary || {} } }];
